<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');} $id=(int)($_GET['id']??0); $config=require __DIR__.'/config.php'; try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$q=$pdo->prepare('SELECT * FROM tiendas WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Tienda no encontrada.');}}catch(Throwable $e){http_response_code(500);exit('No se pudo cargar la tienda.');} function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar tienda</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:650px;margin:auto;padding:30px 20px}.card{background:#fff;padding:25px;border-radius:16px}a{color:#886c42}label{display:block;margin:10px 0 4px}input,select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #ccc;border-radius:7px}button{margin-top:16px;padding:11px 18px;border:0;border-radius:7px;background:#886c42;color:white}</style></head><body><main><p><a href="tiendas-admin.php">← Tiendas</a></p><section class="card"><h1>Editar tienda</h1><form method="post" action="tienda-actualizar.php"><input type="hidden" name="id" value="<?=$s['id']?>"><label>Nombre</label><input name="nombre" required value="<?=h($s['nombre'])?>"><label>Eslogan</label><input name="eslogan" value="<?=h((string)$s['eslogan'])?>"><label>WhatsApp</label><input name="telefono_whatsapp" required value="<?=h($s['telefono_whatsapp'])?>"><label>Dirección</label><input name="direccion" value="<?=h((string)$s['direccion'])?>"><label>Ciudad</label><input name="ciudad" required value="<?=h($s['ciudad'])?>"><label>Modalidad</label><select name="modalidad"><option value="alquilada_fija">Alquilada fija</option><option value="alquilada_comision">Alquilada por comisión</option><option value="administrada">Administrada</option></select><label>Comisión (%)</label><input type="number" name="porcentaje_comision" min="0" max="100" step="0.01" value="<?=h((string)$s['porcentaje_comision'])?>"><label>Estado</label><select name="estado"><option value="activa">Activa</option><option value="suspendida">Suspendida</option><option value="pendiente">Pendiente</option></select><button>Guardar cambios</button></form></section></main></body></html>
